{
  "name": "@dougbots/opencode-image-loader",
  "version": "0.2.2",
  "description": "Image-to-base64 tool for opencode — lets image-capable models see local image files",
  "keywords": [
    "opencode-plugin",
    "image",
    "base64"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/sdougbrown/opencode-image-loader.git"
  },
  "type": "module",
  "files": [
    "dist"
  ],
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "tsdown"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.15.4",
    "@opencode/plugin": "^2.2.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opencode/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.15.4",
    "@opencode/plugin": "2.2.1",
    "@types/bun": "^1.3.12",
    "tsdown": "^0.22.0",
    "typescript": "^5.7.0"
  }
}
